// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListPackingQueue Packing screens' order queue -- every order not yet packed that is either already picked or still pending/processing/on-hold (picking is optional). Each entry carries who is actively working the order right now (lock), if anyone: the UI shows those read-only to everyone else. A lock whose holder sent no heartbeat for 2 minutes is stale and not reported.
	// (GET /packing-queue)
	ListPackingQueue(c *gin.Context, params ListPackingQueueParams)
	// GetPackingSession Packing screen -- get a packing session with its order's line items and scan history
	// (GET /packing-sessions/{id})
	GetPackingSession(c *gin.Context, id Id)
	// CompletePacking Packing screen -- finish a packing session; returns a missing-items report if any order line wasn't fully packed. Always completes (gaps or not) and marks the order packed. completed_by is taken from the caller's own JWT claims.
	// (POST /packing-sessions/{id}/complete)
	CompletePacking(c *gin.Context, id Id)
	// ResetPackingSession Packing screen -- discard every pack scan on this session and release its lock, handing it back fresh. Only legal while the session is in_progress -- 422 once completed.
	// (POST /packing-sessions/{id}/reset)
	ResetPackingSession(c *gin.Context, id Id)
	// ScanPackItem Packing screen -- resolve a scanned code (or an already-known sku_id), match it to the order's own line item, and record it as packed. Rejects (422) a SKU not on the order, or a quantity that would exceed the line item's own ordered quantity.
	// (POST /packing-sessions/{id}/scan)
	ScanPackItem(c *gin.Context, id Id)
	// DeletePackScan Packing screen -- remove a pack scan (fix a mis-scan, or move an item to a different box). Only legal while the session is still in_progress.
	// (DELETE /packing-sessions/{id}/scans/{scanId})
	DeletePackScan(c *gin.Context, id Id, scanId string)
	// TouchPackingSession Packing screen -- heartbeat call while a packing session stays open, refreshing the caller's lock. Returns 409 if another user has since taken over the lock.
	// (POST /packing-sessions/{id}/touch)
	TouchPackingSession(c *gin.Context, id Id)
	// GetPickingSession Scanner app -- get a picking session with its order's line items and scan history, for the progress view
	// (GET /picking-sessions/{id})
	GetPickingSession(c *gin.Context, id Id)
	// CompletePicking Scanner app -- finish a picking session; returns a missing-items report if any order line wasn't fully picked/substituted. Always marks the order fulfilled, gaps or not. completed_by is taken from the caller's own JWT claims, not the request body. If a substitute/ freebie/new-item pick's SKU is short on tracked stock, returns completed:false with stock_shortfalls instead of completing -- resubmit with resolutions once staff decide.
	// (POST /picking-sessions/{id}/complete)
	CompletePicking(c *gin.Context, id Id)
	// PausePicking Scanner app -- pause an in-progress picking session
	// (POST /picking-sessions/{id}/pause)
	PausePicking(c *gin.Context, id Id)
	// RefundLineItem Scanner app -- stage refunding part or all of an existing line item's own quantity, when staff choose not to substitute it. Real money only moves at session completion (see PickScan's doc and CompletePickingUseCase); if the order has no known payment provider or the refund API call fails, the order is instead flagged for manual review rather than blocking completion. A customer_user caller needs the oms.line_item.refund permission (403 otherwise).
	// (POST /picking-sessions/{id}/refund)
	RefundLineItem(c *gin.Context, id Id)
	// ResetPickingSession Scanner/admin app -- discard every staged scan on this session and release its lock, handing it back fresh (e.g. picker wants to switch boxes or start the pick over). Only legal while the session is in_progress or paused -- 422 once it's completed, same one-way- door rule as DELETE .../scans/{scanId}.
	// (POST /picking-sessions/{id}/reset)
	ResetPickingSession(c *gin.Context, id Id)
	// ResolvePickScanCode Scanner app -- resolve a scanned barcode/box-alias/SKU code (or this order's own line items) to a SKU, without staging anything yet. Lets the app show a confirm screen before staging a PickScan via POST .../scan.
	// (POST /picking-sessions/{id}/resolve-scan)
	ResolvePickScanCode(c *gin.Context, id Id)
	// ScanPickItem Scanner app -- resolve a scanned code (or an already-known sku_id) and stage a pick/freebie/new_item action. Never touches real inventory or the order's line items -- see PickScan's doc. Rejects action_type substitute (422) -- use POST .../substitute-batch instead.
	// (POST /picking-sessions/{id}/scan)
	ScanPickItem(c *gin.Context, id Id)
	// DeletePickScan Scanner app -- remove a staged scan before it's been replayed (fix a mis-scan). Only legal while the session is still in_progress.
	// (DELETE /picking-sessions/{id}/scans/{scanId})
	DeletePickScan(c *gin.Context, id Id, scanId string)
	// SubstituteLineItem Scanner app -- stage one or more Substitute PickScan rows for the same original line item in a single call, one per substitute SKU. Lets a single original unit be replaced by several different (typically cheaper) substitutes at once. lines' original_quantity_covered must sum to the original line item's own quantity exactly. Never touches real inventory or the order's line items -- see PickScan's doc.
	// (POST /picking-sessions/{id}/substitute-batch)
	SubstituteLineItem(c *gin.Context, id Id)
	// TouchPickingSession Scanner/admin app -- heartbeat call while a picking session stays open, refreshing the caller's lock so it doesn't go stale under PickingLockTTL. Returns 409 if another user has since taken over the lock (this caller's own session expired and someone else started it).
	// (POST /picking-sessions/{id}/touch)
	TouchPickingSession(c *gin.Context, id Id)
	// ListSalesOrders List sales orders for the current tenant, newest first
	// (GET /sales-orders)
	ListSalesOrders(c *gin.Context, params ListSalesOrdersParams)
	// CreateSalesOrder Manually create a sales order (e.g. a walk-in the POS wasn't used for)
	// (POST /sales-orders)
	CreateSalesOrder(c *gin.Context)
	// BulkUpdateSalesOrderStatus Apply the same status and/or fulfilled change to many orders at once -- the Sales Orders page's bulk action bar. Every order_id is attempted independently: one failing (e.g. since deleted) does not stop the rest, see the response's updated/failed split.
	// (POST /sales-orders/bulk-status)
	BulkUpdateSalesOrderStatus(c *gin.Context)
	// GetPickList Read-only pick list across several sales orders -- what to fetch off the shelves, quantities summed per SKU with a per-order breakdown. The lightweight alternative to a picking session: the item-by-item scanning then happens during packing. Refunded quantities are excluded. Nothing is written.
	// (GET /sales-orders/pick-list)
	GetPickList(c *gin.Context, params GetPickListParams)
	// DeleteSalesOrder Delete a sales order -- restocks first if its stock had been decremented
	// (DELETE /sales-orders/{id})
	DeleteSalesOrder(c *gin.Context, id Id)
	// GetSalesOrder Get one sales order with its line items
	// (GET /sales-orders/{id})
	GetSalesOrder(c *gin.Context, id Id)
	// UpdateSalesOrder Update a sales order's header fields (status, customer, notes, etc) -- never line items
	// (PATCH /sales-orders/{id})
	UpdateSalesOrder(c *gin.Context, id Id)
	// ListSalesOrderActivities The order's activity log, newest first -- structured, system-recorded entries (MyParcel order export, shipment creation, label print, and their failures), each tied to the acting user. Separate from the single freeform customer_note field on SalesOrder.
	// (GET /sales-orders/{id}/activities)
	ListSalesOrderActivities(c *gin.Context, id Id)
	// ForceAcceptStock Bypass the insufficient-stock check for every SKU-linked pending line item on this order -- the "Stock Issues" admin page's override action, for when staff know the item physically exists and the tracked ledger is simply wrong. Writes a reconciliation adjustment for whatever's short, same escape hatch POS sales already use, then completes the sale. Unlike retry-stock, this always resolves every eligible line item -- there is no still_pending outcome. A SKU-less line item is left untouched; link it via link-sku first.
	// (POST /sales-orders/{id}/force-accept-stock)
	ForceAcceptStock(c *gin.Context, id Id)
	// AddSalesOrderLineItem Append a new line item to an already-existing order -- unlike every other line-item write, which happens once at order creation (line items are otherwise immutable). Used by CompletePickingUseCase's freebie/new_item replay when a picker adds a product to the order mid-pick that was never on it. Does not touch stock -- the caller records that separately. Bumps the order's total_minor_units.
	// (POST /sales-orders/{id}/line-items)
	AddSalesOrderLineItem(c *gin.Context, id Id)
	// LinkLineItemSKU Link a line item that was imported without a matching catalog SKU (sku_id nil) to a real SKU -- the "Unmatched SKUs" admin page's resolve action. Does not itself retry the stock decrement -- call retry-stock separately afterward.
	// (POST /sales-orders/{id}/line-items/{lineItemId}/link-sku)
	LinkLineItemSKU(c *gin.Context, id Id, lineItemId string)
	// StartOrResumePacking Packing screen -- start a new packing session for this order, or resume its existing in_progress one. Picking is optional: an order that was never picked may be packed directly while its status is pending/processing/on-hold. An open picking session is taken over (closed as abandoned) when its lock is stale (no heartbeat for 2 minutes), is the caller's own, or the caller is an admin (super_admin/customer_owner/customer_admin); the same takeover rule applies to another user's packing lock. Rejected (422) if the order is already packed, or unpicked in any other status; 409 if someone else actively holds the picking or packing lock, or the picking session still has unapplied changes. Completing packing also marks the order fulfilled.
	// (POST /sales-orders/{id}/packing)
	StartOrResumePacking(c *gin.Context, id Id)
	// StartOrResumePicking Scanner app -- start a new picking session for this order, or resume its existing in_progress/paused one. Picking is optional. Rejected (422) if the order is already fulfilled or packed; 409 if the order has a packing session in progress, or another user actively holds the session's lock (see PickingSession.locked_by). A lock is stale after 2 minutes without a heartbeat; admins (super_admin/customer_owner/customer_admin) may take over an active one, and the previous holder's next scan/heartbeat then gets 409.
	// (POST /sales-orders/{id}/picking)
	StartOrResumePicking(c *gin.Context, id Id)
	// RetryStockDecrement Retry the stock decrement for every line item on this order whose decrement is pending (SKU linked, but the earlier attempt hit insufficient stock) -- the "Stock Issues" admin page's resolve action, run after staff fix the underlying stock. A line item still insufficient after retrying is reported in the response, not an error for the call as a whole.
	// (POST /sales-orders/{id}/retry-stock)
	RetryStockDecrement(c *gin.Context, id Id)
}

